    max-width: var(--layout-max-width);
    margin: 0 auto;
}

.news-card {
    position: relative;
    grid-column: span 6;
    min-height: 450px;
    background: rgba(var(--morpho-bg-secondary-rgb), 0.1);
    border: 1px solid rgba(var(--morpho-accent-primary-rgb), 0.2);
    padding: 2.5rem;
    display: flex;
    flex-direction: var(--layout-card-direction);
    justify-content: flex-end;
    text-decoration: none;
    overflow: hidden;
    backdrop-filter: blur(5px);
    clip-path: polygon(0 0, 95% 0, 100% 5%, 100% 100%, 5% 100%, 0 95%);

    /* Scroll-driven Animation */
    view-timeline-name: --card-warp;
    view-timeline-axis: block;
    animation: var(--layout-animation-style) both linear;
    animation-timeline: --card-warp;
    animation-range: entry 0% cover 50%;
}

/* 不規則なグリッド配置によるダイナミズム */
.news-card:nth-child(3n+1) {
    grid-column: span 7;
    margin-left: -2rem;
}

.news-card:nth-child(3n+2) {
    grid-column: span 5;
    margin-top: 5rem;
}

.news-card:nth-child(3n+3) {
    grid-column: 4 / span 8;
    margin-right: -2rem;
}

